import RNA, random, sys, time

target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..)).".replace(' ','')
n = len(target)

stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j

unpaired = [i for i in range(n) if i not in pairs]
pair_list = [(i,j) for i,j in pairs.items() if i<j]

def fold(seq):
    fc = RNA.fold_compound(seq)
    struct, mfe = fc.mfe()
    return struct, mfe

def bp_distance(s1, s2):
    return RNA.bp_distance(s1, s2)

def random_pair_bases(strength='gc'):
    if strength=='gc':
        return random.choice([('G','C'),('C','G')])
    elif strength=='au':
        return random.choice([('A','U'),('U','A')])
    else:
        return random.choice([('G','U'),('U','G')])

def init_seq(seed):
    random.seed(seed)
    seq = ['A']*n
    for (i,j) in pair_list:
        r = random.random()
        if r < 0.55:
            a,b = random_pair_bases('gc')
        elif r < 0.85:
            a,b = random_pair_bases('au')
        else:
            a,b = random_pair_bases('gu')
        seq[i]=a; seq[j]=b
    for i in unpaired:
        seq[i] = random.choice(['A','A','U','C'])
    return seq

def mutate_position(seq, pos):
    # if paired, mutate the pair together
    if pos in pairs:
        j = pairs[pos]
        i = min(pos,j); jj = max(pos,j)
        r = random.random()
        if r < 0.5:
            a,b = random_pair_bases('gc')
        elif r < 0.8:
            a,b = random_pair_bases('au')
        else:
            a,b = random_pair_bases('gu')
        seq[i]=a; seq[jj]=b
    else:
        seq[pos] = random.choice(['A','C','G','U'])

def run_search(seed, iters, time_budget):
    seq = init_seq(seed)
    s = ''.join(seq)
    struct, mfe = fold(s)
    best_dist = bp_distance(struct, target)
    best_seq = seq[:]
    cur_dist = best_dist
    t0 = time.time()
    no_improve = 0
    for it in range(iters):
        if time.time() - t0 > time_budget:
            break
        # find mismatched positions between struct and target
        mismatches = [k for k in range(n) if struct[k] != target[k]]
        if not mismatches:
            break
        # pick a few mismatched positions to mutate
        trial = seq[:]
        npos = random.choice([1,1,1,2,2,3])
        positions = random.sample(mismatches, min(npos, len(mismatches)))
        for p in positions:
            mutate_position(trial, p)
        s2 = ''.join(trial)
        struct2, mfe2 = fold(s2)
        dist2 = bp_distance(struct2, target)
        if dist2 <= cur_dist or random.random() < 0.03:
            seq = trial
            struct = struct2
            cur_dist = dist2
            if dist2 < best_dist:
                best_dist = dist2
                best_seq = trial[:]
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1
        if dist2 == 0:
            break
        if no_improve > 400:
            # random restart partially
            seq = init_seq(random.randint(0,10**6))
            s = ''.join(seq)
            struct, mfe = fold(s)
            cur_dist = bp_distance(struct, target)
            no_improve = 0
    return ''.join(best_seq), best_dist

if __name__ == "__main__":
    seed = int(sys.argv[1]) if len(sys.argv)>1 else 0
    iters = int(sys.argv[2]) if len(sys.argv)>2 else 3000
    budget = float(sys.argv[3]) if len(sys.argv)>3 else 60
    best_seq, best_dist = run_search(seed, iters, budget)
    print(best_dist, best_seq)
